import json, os, subprocess, sys, tempfile

def check_wc():
    """Run tests/ plus functional checks for the new --top/--json options; print PASS only when all hold."""
    out = tools.run_command(command="python3 -m pytest tests/ -q")
    if "[exit code 0]" not in out:
        return "TESTS FAILED:\n" + out[-1500:]
    ok = True
    notes = []
    # default output unchanged
    out_def = subprocess.run([sys.executable, "wc.py", "sample.txt"], capture_output=True, text=True)
    lines = out_def.stdout.splitlines()
    if lines[:4] != ["lines: 4", "words: 12", "unique: 8", "the 3"]:
        ok = False; notes.append(f"default output wrong: {lines[:4]}")
    # --top 2, options before file
    out2 = subprocess.run([sys.executable, "wc.py", "--top", "2", "sample.txt"], capture_output=True, text=True)
    l2 = out2.stdout.splitlines()
    if len(l2) != 4 or l2[0] != "lines: 4" or l2[2] != "unique: 8" or len(l2) < 5 or "the 3" != l2[3]:
        ok = False; notes.append(f"--top 2 before file wrong: {l2}")
    # --top 2 after file
    out3 = subprocess.run([sys.executable, "wc.py", "sample.txt", "--top", "2"], capture_output=True, text=True)
    if out3.stdout != out2.stdout:
        ok = False; notes.append("--top after file differs")
    # --json honors default top 5
    outj = subprocess.run([sys.executable, "wc.py", "--json", "sample.txt"], capture_output=True, text=True)
    try:
        j = json.loads(outj.stdout)
        if j["lines"] != 4 or j["words"] != 12 or j["unique"] != 8 or len(j["top"]) != 5 or j["top"][0] != ["the", 3]:
            ok = False; notes.append(f"json default wrong: {j}")
    except Exception as e:
        ok = False; notes.append(f"json not valid: {e}: {outj.stdout[:200]}")
    # --json --top 2
    outj2 = subprocess.run([sys.executable, "wc.py", "sample.txt", "--json", "--top", "2"], capture_output=True, text=True)
    try:
        j2 = json.loads(outj2.stdout)
        if len(j2["top"]) != 2 or j2["top"][0] != ["the", 3]:
            ok = False; notes.append(f"json --top 2 wrong: {j2}")
    except Exception as e:
        ok = False; notes.append(f"json --top 2 not valid: {e}")
    # missing file -> stderr + exit 2
    outm = subprocess.run([sys.executable, "wc.py", "nope.txt"], capture_output=True, text=True)
    if outm.returncode != 2 or outm.stderr.strip() != "error: no such file: nope.txt":
        ok = False; notes.append(f"missing file: rc={outm.returncode} err={outm.stderr!r}")
    if ok:
        return "PASS"
    return "CHECKS FAILED:\n" + "\n".join(notes)

